ulation.un.org/wup/assets/Download/Cities/WUP2025-F21-DEGURBA-Cities_Pop.xlsx"],"subjectKey":"world:comparison:b7f60430287378654e2a","topic":"Größenvergleiche","iso":"PL","comparison":{"metric":"cityPopulation","label":"Einwohnerzahl urbaner Zentren","year":2025,"unit":"Einwohner","rule":"rank3","rank":3,"minimumRatio":1.25,"values":[{"id":"un-wup2025-5245","iso":"JP","name":"Nagoya","value":7146160,"display":"7,1 Mio. Einwohner"},{"id":"un-wup2025-3878","iso":"KR","name":"Busan","value":3263221,"display":"3,3 Mio. Einwohner"},{"id":"un-wup2025-3660","iso":"PL","name":"Warschau","value":1882756,"display":"1,9 Mio. Einwohner"},{"id":"un-wup2025-1754","iso":"NL","name":"Amsterdam","value":1235985,"display":"1,2 Mio. Einwohner"}]}}}]$seed$::jsonb)
